INSERT INTO `medical_sessions` VALUES (1,2,3,NULL,'2026-03-27','<p>Bệnh nhân đã được khám Chiro và Đông y buổi đầu tiên. Lúc đó chưa có app để nhập nên dữ liệu còn thiếu sót.</p>','<p>Lịch hẹn lần tới là 30.03.26</p>','active','2026-03-27 03:18:01','2026-03-27 05:26:33'),(2,23,1,NULL,'2026-03-27',NULL,NULL,'active','2026-03-27 07:35:38','2026-03-27 07:35:38'),(3,30,3,NULL,'2026-03-27',NULL,NULL,'active','2026-03-27 09:46:42','2026-03-27 09:46:42'),(4,54,3,NULL,'2026-03-28',NULL,NULL,'active','2026-03-28 06:54:56','2026-03-28 06:54:56'),(5,54,1,NULL,'2026-03-29',NULL,NULL,'active','2026-03-29 01:49:06','2026-03-29 01:49:06'),(6,59,1,NULL,'2026-03-29',NULL,NULL,'active','2026-03-29 02:14:47','2026-03-29 02:14:47'),(7,52,1,NULL,'2026-03-29','<p><br></p>','<p><br></p>','completed','2026-03-29 03:14:47','2026-03-29 15:01:15'),(8,60,1,NULL,'2026-03-29',NULL,NULL,'active','2026-03-29 04:29:52','2026-03-29 04:29:52'),(9,62,1,NULL,'2026-03-29',NULL,NULL,'active','2026-03-29 06:58:15','2026-03-29 06:58:15'),(10,53,4,NULL,'2026-03-29','<p><br></p>','<p><br></p>','completed','2026-03-29 14:52:06','2026-03-29 15:01:44'),(11,10,4,NULL,'2026-03-29','<p><br></p>','<p><br></p>','completed','2026-03-29 15:03:23','2026-03-30 10:30:39'),(12,64,1,NULL,'2026-03-30','<p>Bị lao hạch cổ bên phải, mổ 2 lần. </p>','<p><br></p>','active','2026-03-30 02:01:36','2026-03-30 08:20:27'),(13,65,1,NULL,'2026-03-30',NULL,NULL,'active','2026-03-30 02:11:36','2026-03-30 02:11:36'),(14,66,1,NULL,'2026-03-30',NULL,NULL,'active','2026-03-30 03:38:57','2026-03-30 03:38:57'),(15,58,1,NULL,'2026-03-30','<p>bị một hạch bạch huyết (lymp knoten) nhỏ dưới tai phải. Johanna làm thông vùng cổ phải.</p>','<p><br></p>','active','2026-03-30 04:08:47','2026-03-30 08:10:15'),(16,54,4,NULL,'2026-03-30',NULL,NULL,'active','2026-03-30 09:11:00','2026-03-30 09:11:00'),(17,53,8,NULL,'2026-03-30','<p><br></p>','<p><br></p>','completed','2026-03-30 09:14:39','2026-03-30 09:27:00'),(18,61,4,NULL,'2026-03-30','<p><br></p>','<p><