INSERT INTO `treatments` VALUES (1,54,4,NULL,NULL,'28.3.2026 hơ ngải bụng 30p,thận du,mệnh môn 10p, đại chuỳ 5p,túc tam lý 3p. day bổ đường kinh thận, tỳ 10p. giải cơ vai gáy,lưng 30p,bấm huyệt đầu 10p. Sau buổi điều trị bn ngủ sâu giấc 1h tại pk.',NULL,NULL,'2026-03-29 21:45:18',4,'paid'),(2,54,4,NULL,NULL,'29.3.2026 đả thông kinh lạc toàn bộ lưng 45p. hơ ngải đại chuỳ,thận du,mệnh môn,quan nguyên, khí hải,trung quản,túc tam lý,tam âm giao 30p.day bổ đường kinh thận,day huyệt đầu mặt 15p.',NULL,NULL,'2026-03-29 21:49:35',4,'paid'),(3,53,4,NULL,NULL,'29.3.2026 đả thông kinh lạc vùng gáy,lưng 60p. giải cơ đù, đầu gối trái 10p, hơ ngải Quan nguyên, trung quản,thần khuyết 10p, bấm huyệt đầu mặt 10p.',NULL,NULL,'2026-03-29 22:00:27',10,'paid'),(4,10,4,NULL,NULL,'đả thông kinh lạc gáy,lưng 30p. hơ toàn bộ lưng, bụng 40p, day bổ đường kinh thận, tỳ, nội quan, thần môn, bấm huyệt đầu mặt, diện chẩn 20p.',NULL,NULL,'2026-03-29 22:10:30',11,'paid'),(5,61,4,NULL,NULL,'đả thông kinh lạc vùng gáy, lưng 50p.giải cơ hình lê.hơ ngải đại chuỳ,mệnh môn,thận du,quan nguyên, trung quản,thần khuyết,túc tam lý 30p. bấm huyệt vào tk số 3, vùng mắt phải 10p. ',NULL,NULL,'2026-03-30 16:41:12',18,'paid'),(6,51,4,NULL,NULL,'cào đầu, diện chẩn, bấm huyệt vùng đầu 15p. đả thông kinh lạc vùng vai gáy, lưng 45p. hơ mệnh môn, trung quản,thần khuyết, túc tam lý, đại chuỳ, mệnh môn, thận du 25p. bấm huyệt tay trái 5p.',NULL,NULL,'2026-04-01 12:03:53',28,'paid'),(7,65,4,NULL,NULL,'sau buổi điều trị lần 1 đã ngủ sâu giấc hơn.Kỹ thuật gồm đả thông kinh lạc vùng gáy 30p, lưng 20p. hơ và khai thông kinh lạc bụng, tập trung nhiều vào vết sẹo mổ 30p.Bấm huyệt vùng đầu 10p.',NULL,NULL,'2026-04-01 12:16:27',29,'paid'),(8,58,4,NULL,NULL,'hơ ngải cứu và ấn huyệt bụng, túc tam lý, thận du 20p. bấm huyệt khai thông cổ vai gáy, tập trung gáy và vùng xương đòn, cổ bên phải 25p. bấm huyệt thận du và bát liêu 10p. bấm huyệt đầu mặt 5p.',NULL,NULL,'2026-04-01 12:28:19',30,'paid'),(9,58,4,NULL,NULL,'kiện tỳ ~ điều vị, giải cơ chân, vai, nửa lưng trên ',NULL,NULL,'2026-04-02 10:33:20',35,'paid'),(10,42,4,NULL,NULL,'day bổ đường kinh thận, day bổ đường kinh tỳ. day ấn huyệt quan nguyên, khí hải, trung quản,túc tam lý. Hơ ngải thần khuyết. diện chẩn: bổ trung có dầu, an thần có dầu. bấm huyệt vùng đầu',NULL,NULL,'2026-04-02 10:45:30',36,'paid'),(11,10,4,NULL,NULL,'đau bắp chân phải nhiều,leo cầu thang khó,đi tiểu đêm nhiều,tiêu hoá yếu, stress.                      .hơ và day ấn huyệt quan nguyên,khí hải,trung quản,thần khuyết,túc tam lý,toàn bộ lưng.\r\n.đả thông kinh lạc chân, lắp máy bóp chân.            .bấm huyệt đầu. chú ý bệnh này thần kinh nhạy cảm.                    ',NULL,NULL,'2026-04-02 10:59:41',33,'paid'),(12,10,4,NULL,NULL,'đau bắp chân phải nhiều,leo cầu thang khó,đi tiểu đêm nhiều,tiêu hoá yếu, stress.                      .hơ và day ấn huyệt quan nguyên,khí hải,trung quản,thần khuyết,túc tam lý,toàn bộ lưng.\r\n.đả thông kinh lạc chân, lắp máy bóp chân.            .bấm huyệt đầu. chú ý bệnh này thần kinh nhạy cảm.                    ',NULL,NULL,'2026-04-02 10:59:41',33,'paid'),(13,10,4,NULL,NULL,'đau bắp chân phải nhiều,leo cầu thang khó,đi tiểu đêm nhiều,tiêu hoá yếu, stress.                      .hơ và day ấn huyệt quan nguyên,khí hải,trung quản,thần khuyết,túc tam lý,toàn bộ lưng.\r\n.đả thông kinh lạc chân, lắp máy bóp chân.            .bấm huyệt đầu. chú ý bệnh này thần kinh nhạy cảm.                    ',NULL,NULL,'2026-04-02 10:59:41',33,'paid'),(14,58,5,NULL,NULL,'Dưỡng thận, đã thông vai gáy, làm vùng đầu, kiện tỳ điều vị \r\nCứu ngải làm ấm bụng ',NULL,NULL,'2026-04-03 07:40:40',35,'paid'),(15,58,5,NULL,NULL,'Dưỡng thận, đã thông vai gáy, làm vùng đầu, kiện tỳ điều vị \r\nCứu ngải làm ấm bụng ',NULL,NULL,'2026-04-03 07:44:38',35,'paid'),(16,58,5,NULL,NULL,'Dưỡng thận, đã thông vai gáy, làm vùng đầu, kiện tỳ điều vị \r\nCứu ngải làm ấm bụng ',NULL,NULL,'2026-04-03 07:45:35',35,'paid'),(17,58,5,NULL,NULL,'Dưỡng thận, đã thông vai gáy, làm vùng đầu, kiện tỳ điều vị Cứu ngải làm ấm bụng',NULL,NULL,'2026-04-03 08:00:47',38,'paid'),(18,44,7,NULL,NULL,'Làm bụng, hơ ngãi cứu bụng, giãn cơ chân, làm đầu, ',NULL,NULL,'2026-04-04 11:54:56',45,'paid'),(19,44,7,NULL,NULL,'Làm bụng, hơ ngãi cứu bụng, giãn cơ chân, làm đầu, ',NULL,NULL,'2026-04-04 11:55:48',45,'paid'),(20,44,7,NULL,NULL,'Làm bụng, hơ ngãi cứu bụng, giãn cơ chân, làm đầu, ',NULL,NULL,'2026-04-04 11:55:57',45,'paid'),(21,44,7,NULL,NULL,'Làm bụng, hơ ngãi cứu bụng, giãn cơ chân, làm đầu, ',NULL,NULL,'2026-04-04 11:57:01',45,'paid'),(22,40,5,NULL,NULL,'Vai + lưng + kiện tỳ điều vị ',NULL,NULL,'2026-04-04 11:58:10',41,'paid'),(23,22,7,NULL,NULL,'Làm bụng, hơ ngãi bụng, hơ ngãi vai gáy, giải cơ vai gáy,làm đầu.',NULL,NULL,'2026-04-04 12:10:04',47,'paid'),(24,22,7,NULL,NULL,'Làm bụng, hơ ngãi bụng, hơ ngãi vai gáy, giải cơ vai gáy,làm đầu.',NULL,NULL,'2026-04-04 12:10:31',47,'paid'),(25,76,4,NULL,NULL,'vùng bụng cứng,tắc,đau nhiều khi ấn. day đường kinh tâm, đản trung đau nhiều. \r\nkỹ thuật: 1.day bấm đả thông tỳ vị <anh Hoài>\r\n2.day bổ đường kinh tâm,tâm bào,day kỹ đại chuỳ, vùng gáy, thận du. <Lộc>\r\n3. đả thông hai chân, hơ ngải <Thương>\r\n',NULL,NULL,'2026-04-04 14:31:21',46,'paid'),(26,70,4,NULL,NULL,'phần gáy còn cứng nhiều, vùng đầu còn tắc.  \r\nbấm huyệt vùng đầu, xoang có dầu. đả thông vai gáy, bấm nội quan, thái uyên, khúc trì',NULL,NULL,'2026-04-04 14:40:50',49,'paid'),(27,41,4,NULL,NULL,'hiện tượng sương mù trong não giảm 50%, chân tê,gáy còn mỏi, bụng đã mềm hơn.\r\n1.day bấm vùng đầu,day kỹ đại chuỳ <Lộc>\r\n2.tác động cột sống <Nga>\r\n3.Đả thông tỳ vị <Hoài>',NULL,NULL,'2026-04-04 14:53:38',50,'paid'),(28,58,4,NULL,NULL,'day bổ thận kinh,tỳ kinh,đại trường,đả thông xoang,vùng đầu.\r\n1.day huyệt vùng đầu cổ.\r\n2.vuốt đường kinh đại trường,tiểu trường,huyệt thận du, đại chuỳ.',NULL,NULL,'2026-04-04 14:58:27',38,'paid'),(29,74,5,NULL,NULL,'Vai ,lưng và kiện tỳ điều vị ',NULL,NULL,'2026-04-04 15:04:56',52,'paid'),(30,73,4,NULL,NULL,'đã bỏ thuốc an thần buổi tối. thuốc ngủ còn 1|2 liều. dễ căng thẳng, lo lắng. gia đình có di truyền mất ngủ, rối loạn lo âu.\r\nbấm huyệt vùng đầu, vai gáy, lưng. đả thông 2 chân. hơ ngải bụng 7p. thắt lưng 10p',NULL,NULL,'2026-04-04 15:06:46',51,'paid'),(31,53,5,NULL,NULL,'Vai lưng và kiện tỳ điều vị ',NULL,NULL,'2026-04-04 15:08:15',17,'paid'),(32,8,5,NULL,NULL,'Vai lưng và bụng ',NULL,NULL,'2026-04-04 15:10:34',53,'paid'),(33,61,4,NULL,NULL,'vùng mông phải còn tê, tiêu hoá đã ổn định,mắt phải còn yếu.\r\n1.day bấm vùng đầu, mắt phải.\r\n2.đả thông kinh lạc vai gáy,lưng,mông,chân.\r\n3.day bấm huyệt vùng bụng.',NULL,NULL,'2026-04-04 15:12:14',42,'paid'),(34,71,4,NULL,NULL,'Xoang thường xuyên đau đầu,choáng,táo bón.\r\nbấm huyệt vùng đầu mặt,vai gáy 50p.\r\ntdcs,hơ ngải. sau khi trị liệu đầu đã nhẹ nhàng. vùng đỉnh đầu và hai bên tai vẫn còn tắc',NULL,NULL,'2026-04-06 12:45:38',34,'paid'),(35,71,4,NULL,NULL,'xoang thường xuyên đau đầu,choáng,xay xẩm. vai gáy cứng,táo bón.\r\nbấm huyệt vùng đầu mặt gáy 50p. hơ ngải bụng, tdcs',NULL,NULL,'2026-04-06 12:48:24',58,'paid'),(36,42,4,NULL,NULL,'vẫn còn sợ gió, sợ lạnh. ngủ sâu, ăn ngon miệng hơn.\r\nday bấm huyệt đầu mặt 30p. vuốt đường kinh thận, day bấm,hơ ngải bụng. day kỹ đại chuỳ, thận du, thần môn, nội quan, đản trung, túc tam lý, tam âm giao',NULL,NULL,'2026-04-06 12:53:17',59,'paid'),(37,41,4,NULL,NULL,'bụng vẫn còn tắc, thường xuyên đau đầu, mệt mỏi, từ thắt lưng xuống hai chân bị căng,mỏi,cúi xuống khó khăn.\r\nday bấm đầu mặt, day bấm,hơ ngải bụng.\r\nđả thông vùng gáy thắt lưng,hai chân. hơ ngải vùng thắt lưng.\r\nđã cúi nhẹ nhàng, bớt mệt mỏi nhiều',NULL,NULL,'2026-04-06 13:22:50',60,'paid'),(38,81,4,NULL,NULL,'tay phải căng cơ,đau do chấn thương thể thao và tính chất công việc dùng lực cánh tay nhiều. viêm gan siêu vi B, mỡ máu, gan nhiễm mỡ, có nguy cơ suy thận gd 1 <xét nghiệm ngày 6.4.2026>, tiêu hoá kém.\r\nhay đau nhói thắt lưng.\r\npđ: đả thông kinh lạc vùng vai lưng, bụng.\r\nhơ ngải bụng. thư giãn cơ cánh tay phải \r\n',NULL,NULL,'2026-04-08 12:47:36',65,'paid'),(39,85,4,NULL,NULL,'táo bón, phải sử dụng men tiêu hoá thường xuyên.\r\nbệnh nhân ít vận động, nửa người bên trái bó cứng nhiều.\r\nđả thông kinh lạc lưng gáy,chân. tập trung bên trái nhiều hơn. day ấn hơ ngải bụng, túc tam lý. day bấm huyệt đầu.',NULL,NULL,'2026-04-08 12:51:23',61,'paid'),(40,42,4,NULL,NULL,'người mệt mỏi,tinh thần uể oải,trong ngày cơ thể mệt mỏi thay đổi thất thường.hay bị toát mồ hôi lạnh.\r\nday bấm huyệt vùng đầu mặt,day dầu bổ trung,an thần.hơ day thần môn, nội quan, khúc trì, túc tam lý, tam âm giao. quan nguyên, trung quản, thần khuyết, đại chuỳ, thận du,mệnh môn.',NULL,NULL,'2026-04-08 13:14:13',39,'paid'),(41,1,2,NULL,NULL,'QA Test Session: Checking redirect to checkout page.',NULL,NULL,'2026-04-10 21:47:01',NULL,'unpaid');
